<script setup>import{Link}from'@inertiajs/vue3';import AdminLayout from'../../Layouts/AdminLayout.vue';defineProps({stats:Object,recentOrders:Array,recentSyncs:Array});</script><template><AdminLayout><div class="flex items-end justify-between"><div><p class="section-kicker">Overview</p><h1 class="section-title">Dashboard</h1></div><Link href="/admin/products/create" class="btn-primary">Add product</Link></div><div class="mt-6 grid grid-cols-2 gap-3 lg:grid-cols-4"><div class="metric-card"><p class="text-xs font-bold text-slate-500">Products</p><p class="mt-2 text-2xl font-black">{{stats.products}}</p></div><div class="metric-card"><p class="text-xs font-bold text-slate-500">Pending orders</p><p class="mt-2 text-2xl font-black">{{stats.pending_orders}}</p></div><div class="metric-card"><p class="text-xs font-bold text-slate-500">Low stock</p><p class="mt-2 text-2xl font-black text-amber-600">{{stats.low_stock_products}}</p></div><div class="metric-card"><p class="text-xs font-bold text-slate-500">Out of stock</p><p class="mt-2 text-2xl font-black text-red-600">{{stats.out_of_stock_products}}</p></div></div><div class="mt-6 grid gap-5 lg:grid-cols-2"><section class="card p-5"><h2 class="font-black">Recent orders</h2><div class="mt-3 divide-y"><Link v-for="o in recentOrders" :key="o.id" :href="`/admin/orders/${o.id}`" class="flex justify-between py-3 text-sm"><span><b>{{o.order_number}}</b><br><span class="text-slate-500">{{o.customer_name}}</span></span><span class="text-right"><b>TZS {{Number(o.grand_total).toLocaleString()}}</b><br><span class="capitalize text-slate-500">{{o.status}}</span></span></Link></div></section><section class="card p-5"><h2 class="font-black">Store health</h2><div class="mt-4 grid gap-3 text-sm"><Link href="/admin/products?status=draft" class="flex justify-between"><span>Draft products</span><b>{{stats.products-stats.active_products}}</b></Link><Link href="/admin/inquiries" class="flex justify-between"><span>New service requests</span><b>{{stats.new_inquiries}}</b></Link><Link href="/admin/merchant" class="flex justify-between"><span>Failed Merchant syncs</span><b>{{stats.failed_syncs}}</b></Link></div></section></div></AdminLayout></template>
